{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Olsalazine sodium had a systemic availability of only 2.3% after a 1 g oral dose in fasting healthy volunteers, providing affirmative evidence that an oral drug can fall far below the 20% bioavailability threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Chloramphenicol, a nitroaromatic amide, showed >100% oral bioavailability in children, indicating high F in a remotely related scaffold; low Morgan similarity limits transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Vismodegib, a chlorophenyl amide, had absolute oral bioavailability of 31.8% after a 150 mg oral dose, above the 20% threshold but saturable; low structural similarity limits its weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C40"],
      "claim": "Tolcapone, a nitro-substituted phenol, had absolute oral bioavailability of about 60% in healthy volunteers, high but structurally distant from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query is a poorly soluble salicylanilide (niclosamide) expected to have minimal systemic absorption. The only affirmative low-F analogue (olsalazine, F=2.3%) supports low, while the numerous high-F analogues are structurally distant (Morgan ~0.24-0.27) and carry limited transfer weight.",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement for niclosamide is present in the evidence set.",
    "All retrieved analogues have low Morgan similarity (<0.28), limiting transferability.",
    "No close structural analogue with measured low F is available; the low-F evidence comes from olsalazine, a structurally different azo salicylate."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

